// CSD_RATIONALE_BEGIN
// Strategy: GSM-symbolic arithmetic solver that allows free chain-of-thought reasoning
// and then forces a single hard-parser constrained span <<int(formula)>> for the answer.
//
// AppendTaskGuidance primes the model with explicit format instructions before any generation.
// Phase 0 closes any inherited open constrained span immediately (at most 30 steps), so the
// remainder of the budget is always spent in a clean free→constrained progression.
// Phase 1 runs free unconstrained generation for up to 78% of the total budget so the model
// can produce natural chain-of-thought before the answer span. If the model voluntarily emits
// "<<" (detected with RenderedEndsWith to handle tokenizer splits and leading spaces), we
// record that span entry without appending another delimiter.
// Phase 2 forces a "<<" open via OpenConstrainedSpan if free generation did not produce one,
// guaranteeing that a constrained span always appears in the output.
// Phase 3 drives hard-parser constrained generation token-by-token. Each iteration first
// tries CloseSpanIfComplete; if the parse is already complete the span is closed immediately,
// preventing runaway generation beyond the first valid answer. Otherwise ConstrainedStep
// samples one parser-valid token with a hard mask.
// Phase 4 is a budget-bounded fallback: CloseSpanWithinBudget consumes the remaining budget
// to find and close the best complete parse point if Phase 3 did not close the span (e.g.
// because it was cut short by EOS).
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Phase 0 (CloseSpanWithinBudget): The helper postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut), directly preserving the invariant.
//   Phase 1 loop (UnconstrainedStep): When RenderedEndsWith(generated, "<<") fires we set
//     currentConstrainedOut := []; parser.IsValidPrefix([]) holds by the method precondition
//     parser.IsValidPrefix([]). Otherwise insideConstrainedOut stays false so the antecedent
//     is vacuously false.
//   Phase 2 (OpenConstrainedSpan): The helper sets currentOut := [] and insideOut := true;
//     parser.IsValidPrefix([]) holds by precondition, preserving the invariant.
//   Phase 3 loop closed-branch: CloseSpanIfComplete sets insideOut := false, making the
//     invariant vacuously true for the remainder of that iteration.
//   Phase 3 loop non-closed branch: ConstrainedStep applies a hard grammar mask so the
//     returned token is valid at currentConstrainedOut; AppendConstrainedToken's postcondition
//     then guarantees parser.IsValidPrefix(currentConstrainedOut + [next]).
//   Phase 4 (CloseSpanWithinBudget): Same postcondition guarantee as Phase 0.
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
//   Phase 0: CloseSpanWithinBudget guarantees |generatedOut| <= |generated| + b0 and we
//     add b0 to steps, so the bound is preserved.
//   Phase 1 loop: Each iteration increments steps by 1 and appends at most one token (or
//     breaks on EOS without appending), so the bound is maintained at every step.
//   Phase 2: OpenConstrainedSpan appends exactly one "<<" token and steps increases by 1,
//     so |generated|+1 <= |generatedPrefix| + (steps+1).
//   Phase 3 loop: The closed branch increments steps by 1 and appends at most one ">>" token.
//     The non-closed branch increments steps by 1 for ConstrainedStep and appends at most one
//     parser-valid token (or zero on EOS or invalid), so both paths preserve the bound.
//   Phase 4: CloseSpanWithinBudget guarantees |generatedOut| <= |generated| + b4 and we set
//     steps := maxSteps >= steps + b4, so the bound is preserved.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  // Base case: no budget; all out-parameters are already initialized above.
} else {
  helpers.AppendTaskGuidance(lm,
    "Solve step by step. Write final answer as <<int(formula)>>. " +
    "Formula: bare variable names (no {} braces), numbers, +,-,*,/,//,%,(,),int() only. " +
    "ONE <<int(formula)>> block only, at the very end. No LaTeX, no **, no curly braces. " +
    "Example: <<int(n_1 * price - n_2 * discount)>>");

  var steps: nat := 0;
  var prefixBudget: nat := (maxSteps * 78) / 100;

  // Phase 0: Close any inherited open span with a small budget
  if insideConstrainedOut && steps < maxSteps {
    var b0: nat := if maxSteps - steps > 30 then 30 else maxSteps - steps;
    var g0, i0, c0 := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, b0
    );
    generated := g0;
    insideConstrainedOut := i0;
    currentConstrainedOut := c0;
    steps := steps + b0;
  }

  // Phase 1: Free generation until << detected or prefixBudget reached
  while steps < prefixBudget && !insideConstrainedOut
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }

